import { MigrateDownArgs, MigrateUpArgs, sql } from '@payloadcms/db-postgres';

/**
 * Adds `blogs.published_at`.
 *
 * Generated by `migrate:create`, then edited by hand in two ways:
 *
 *  1. **The unused `payload` and `req` parameters were removed.** `tsconfig`
 *     sets `noUnusedParameters`, so the generated signature is a type error
 *     rather than a lint warning and `next build` fails on it. This recurs on
 *     every generated migration; docs/CONTENT-SOURCE.md records it.
 *  2. **A backfill was added**, which the generator cannot know about.
 *
 * Why the backfill
 * ----------------
 * The field is what the site now prints on a post, in place of `created_at`.
 * Left empty on the 14 existing posts, every one of them would fall back to
 * its creation date — which is the current behaviour, so nothing would look
 * broken — but the listing orders by this column, and a column of NULLs orders
 * by nothing. Copying `created_at` into it makes the new field describe the
 * same reality the old one did from the first deploy, with no editor having to
 * open 14 documents to restate a date the database already holds.
 *
 * `created_at` is the right source rather than an approximation: scripts/
 * migrate/repair-dates.mts already put the original Supabase `created_at` back
 * on every migrated document, so these timestamps are the real publication
 * dates, not the day the migration ran.
 *
 * Drafts are left NULL on purpose. An unpublished post has no publication
 * date, and inventing one would mean it went live backdated the moment someone
 * flipped its status. The `stampPublishedAt` hook on the collection fills it
 * at that point instead.
 *
 * Safety: the column is nullable with no default, which is a catalogue-only
 * change in Postgres 11+ — no table rewrite, no long lock. The single UPDATE
 * writes one new column on rows where it is NULL and touches no existing
 * column. Nothing here drops, truncates or rewrites data, and Payload runs the
 * whole thing in a transaction.
 */
export async function up({ db }: MigrateUpArgs): Promise<void> {
  await db.execute(sql`
   ALTER TABLE "payload"."blogs" ADD COLUMN "published_at" timestamp(3) with time zone;`);

  await db.execute(sql`
    UPDATE "payload"."blogs"
       SET "published_at" = "created_at"
     WHERE "status" = 'published'
       AND "published_at" IS NULL;
  `);

  // After the backfill rather than before it: same result, one fewer index
  // maintenance pass over the rows being written.
  await db.execute(sql`
   CREATE INDEX "blogs_published_at_idx" ON "payload"."blogs" USING btree ("published_at");`);
}

/**
 * As generated, plus IF EXISTS on both statements, so this still works against
 * a partly-applied `up`.
 *
 * Dropping the column does lose any date an editor set by hand. Everything the
 * backfill wrote is recoverable from `created_at`; a correction made in the
 * panel afterwards is not.
 */
export async function down({ db }: MigrateDownArgs): Promise<void> {
  await db.execute(sql`
   DROP INDEX IF EXISTS "payload"."blogs_published_at_idx";
  ALTER TABLE "payload"."blogs" DROP COLUMN IF EXISTS "published_at";`);
}
